<script lang="ts">
  import Chart from '../../lib/Chart.svelte'
  import { autoCurrentUnit, autoPowerUnit, formatCurrent, formatPower, formatSeconds } from '../../lib/format'
  import type { ChartEventMarker, ChartHover, ChartRange, ChartSelectionStats, CurveColors } from '../../types'
  let { tSec, volts, amps, temps, samples, colors, showPower, showTemperature, temperatureAvailable, hideChart, hint, events = [], selectionStats = null, onTogglePower, onToggleTemperature, onOpenDetails, onRangeChange }: { tSec: number[]; volts: Array<number | null>; amps: Array<number | null>; temps: Array<number | null>; samples: number; colors: CurveColors; showPower: boolean; showTemperature: boolean; temperatureAvailable: boolean; hideChart: boolean; hint: string | null; events?: ChartEventMarker[]; selectionStats?: ChartSelectionStats | null; onTogglePower: (checked: boolean) => void; onToggleTemperature: (checked: boolean) => void; onOpenDetails: () => void; onRangeChange: (range: ChartRange) => void } = $props()
  let hover = $state<ChartHover | null>(null)
  let chartEl = $state<{ showAll: () => void; followLatest: () => void; openExport: () => void } | null>(null)
  let currentUnit = $derived(autoCurrentUnit(amps))
  let powerUnit = $derived(autoPowerUnit(volts.map((v, i) => v === null || amps[i] === null ? null : v * amps[i]!)))

  function stat(value: number, digits: number) {
    return Number.isFinite(value) ? value.toFixed(digits) : '—'
  }
</script>

<section class="chart-panel" class:compact={hideChart}>
  <div class="panel-title"><span class="title-group"><strong>{hideChart ? '实时读数' : '实时曲线（电压 / 电流）'}</strong><span class="sample-count">{samples} 个采样点</span></span><div class="actions"><button onclick={onOpenDetails}>状态</button>{#if !hideChart && !hint}<button onclick={() => chartEl?.openExport()}>导出图片</button><button onclick={() => chartEl?.followLatest()}>跟随最新</button><button onclick={() => chartEl?.showAll()}>全览</button>{/if}</div></div>
  {#if !hideChart}
  <div class="legend"><label class="power-toggle"><input type="checkbox" checked={showPower} onchange={(event) => onTogglePower((event.currentTarget as HTMLInputElement).checked)} /> 功率曲线</label><label class="temperature-toggle"><input type="checkbox" checked={showTemperature} disabled={!temperatureAvailable} onchange={(event) => onToggleTemperature((event.currentTarget as HTMLInputElement).checked)} /> 温度曲线</label>{#if hover}<span class="hover-readout">{formatSeconds(hover.t, hover.span)} · V {hover.v === null ? '—' : hover.v.toFixed(3)} · I {formatCurrent(hover.a, currentUnit)}{#if hover.temp !== null} · T {hover.temp.toFixed(1)} °C{/if}</span>{/if}<span class="voltage" style={`color:${colors.voltage}`}>- &nbsp;通道 1（V）</span><span class="current" style={`color:${colors.current}`}>- &nbsp;通道 2（{currentUnit}）</span>{#if showPower}<span class="power" style={`color:${colors.power}`}>- &nbsp;功率（{powerUnit}）</span>{/if}{#if showTemperature && temperatureAvailable}<span class="temperature" style={`color:${colors.temperature}`}>- &nbsp;温度（°C）</span>{/if}</div>
  {#if selectionStats}<div class="selection-summary"><strong>当前区间</strong><span>{stat(selectionStats.duration_s, 2)} s · {selectionStats.count.toLocaleString()} 点</span><span>V {stat(selectionStats.vbus.min, 3)}–{stat(selectionStats.vbus.max, 3)} V</span><span>I {formatCurrent(selectionStats.ibus.min)}–{formatCurrent(selectionStats.ibus.max)}</span><span>P max {formatPower(selectionStats.power.max)}</span><span>{stat(selectionStats.capacity_mah, 3)} mAh · {stat(selectionStats.energy_wh, 3)} Wh</span></div>{/if}
  <div class="chart-wrap">{#if hint}<div class="chart-hint">{hint}</div>{:else}<Chart bind:this={chartEl} {tSec} {volts} {amps} {temps} {events} {colors} {showPower} showTemperature={showTemperature && temperatureAvailable} onHover={(value) => hover = value} {onRangeChange} />{/if}</div>
  {/if}
</section>

<style>
  .chart-panel { min-height: 450px; border: 1px solid #e4e7eb; border-radius: 6px; background: #fff; box-shadow: 0 1px 3px rgb(15 23 42 / 5%); overflow: hidden; }.chart-panel.compact { min-height: 0; }.panel-title { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 9px 14px; border-bottom: 1px solid #e5e7eb; color: #1f2937; font-size: 13px; }.panel-title .title-group { display: flex; align-items: center; gap: 10px; min-width: 0; }.panel-title .sample-count { color: #64748b; font: 10px ui-monospace, Consolas, monospace; white-space: nowrap; }.panel-title .actions { display: flex; align-items: center; gap: 8px; }.panel-title button { padding: 4px 7px; border: 1px solid #cbd5e1; border-radius: 4px; color: #475569; background: #fff; cursor: pointer; font-size: 10px; white-space: nowrap; }.panel-title button:hover { color: #1e293b; background: #f8fafc; }.legend { display: flex; align-items: center; justify-content: flex-end; gap: 18px; padding: 6px 15px 3px; color: #64748b; font: 11px ui-monospace, Consolas, monospace; }.legend .hover-readout { color: #1f2937; font-weight: 600; white-space: nowrap; }.legend .voltage { color: #2563eb; }.legend .current { color: #f59e0b; }.legend .power { color: #8c7040; }.legend .temperature { color: #b45309; }.power-toggle, .temperature-toggle { display: flex; align-items: center; gap: 4px; color: #64748b; font: 10px ui-monospace, Consolas, monospace; cursor: pointer; white-space: nowrap; user-select: none; }.power-toggle { margin-right: auto; }.power-toggle input, .temperature-toggle input { width: 12px; height: 12px; margin: 0; accent-color: #2563eb; cursor: pointer; }.temperature-toggle input:disabled { cursor: default; }.chart-wrap { height: 378px; margin: 0 14px 8px; padding: 8px; border: 1px solid #e4e7eb; border-radius: 4px; background: #fafafa; }.chart-hint { display: grid; place-items: center; height: 100%; color: #94a3b8; font-size: 12px; }
  @media (max-width: 560px) { .chart-panel { min-height: 390px; }.chart-wrap { height: 318px; margin-inline: 8px; }.legend { gap: 8px; padding-inline: 9px; font-size: 9px; }.power-toggle { font-size: 9px; }.panel-title { gap: 6px; padding-inline: 9px; }.panel-title .title-group { gap: 6px; }.panel-title .actions { gap: 6px; } }
  .selection-summary { display: flex; flex-wrap: wrap; gap: 6px 14px; padding: 5px 15px 4px; color: #64748b; font: 10px ui-monospace, Consolas, monospace; }
  .selection-summary strong { color: #334155; }
  .selection-summary span { white-space: nowrap; }
</style>
